def backfill_conteos(apps, schema_editor):
    """
    Recalcula conteo_relevamientos y conteo_actualizaciones para todas las colonias
    basándose en las SolicitudRelevamiento existentes con los flags de finalización activos.
    """
    Colonia = apps.get_model('core', 'Colonia')
    SolicitudRelevamiento = apps.get_model('gerencia', 'SolicitudRelevamiento')

    colonias_con_solicitudes = SolicitudRelevamiento.objects.values_list(
        'colonia_id', flat=True
    ).distinct()

    for colonia_id in colonias_con_solicitudes:
        conteo_r = SolicitudRelevamiento.objects.filter(
            colonia_id=colonia_id,
            relevamiento_terminado=True,
        ).count()
        conteo_a = SolicitudRelevamiento.objects.filter(
            colonia_id=colonia_id,
            actualizacion_terminado=True,
        ).count()
        Colonia.objects.filter(pk=colonia_id).update(
            conteo_relevamientos=conteo_r,
            conteo_actualizaciones=conteo_a,
        )


def reverse_backfill(apps, schema_editor):
    Colonia = apps.get_model('core', 'Colonia')
    Colonia.objects.all().update(conteo_relevamientos=0, conteo_actualizaciones=0)


